CREATE TABLE restaurants (id TEXT PRIMARY KEY, name TEXT NOT NULL, address TEXT NOT NULL, lat REAL, lng REAL, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL); CREATE TABLE price_observations (id TEXT PRIMARY KEY, restaurant_id TEXT NOT NULL REFERENCES restaurants(id), item_name TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents BETWEEN 1 AND 100000), currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency = 'USD'), visit_date TEXT NOT NULL, visit_date_precision TEXT NOT NULL CHECK(visit_date_precision IN ('day', 'month', 'year')), reporter_id TEXT NOT NULL REFERENCES members(id), reported_at TEXT NOT NULL, note TEXT, corrected_from_id TEXT REFERENCES price_observations(id), corrected_at TEXT); CREATE INDEX restaurants_name ON restaurants(name); CREATE UNIQUE INDEX restaurants_identity ON restaurants(name, address); CREATE INDEX price_observations_restaurant ON price_observations(restaurant_id, item_name, visit_date);
